	$expect( $copy === get_post_meta( $id, 'page_content_rows_0_body_text', true ) && $copy === get_post_meta( $id, 'page_content_rows_1_right_column_rows_0_body_text', true ), 'Root/nested rich copy, repeated items and query link remain exact' );
	foreach ( $body as $name => $value ) { if ( str_starts_with( $name, 'list_' ) || in_array( $name, array( 'body_text_mobile_breakpoint', 'body_heading_space_after_mobile' ), true ) ) { $expect( (string) $value === (string) $saved[1]['right_column_rows'][0][ $name ], 'Native ACF retains ' . $name ); } }
	$expect( 'calc(45% - 40px)' === $saved[1]['split_first_column_max'] && '263px' === $saved[1]['left_column_rows'][0]['image_media_max_width'] && '70px' === $saved[1]['left_column_rows'][0]['image_media_max_height_mobile'], 'Native ACF retains proportional bounds and intrinsic logo limits' );
