	$expect( 6 === substr_count( $html, '<li>' ) && 4 === substr_count( $html, 'Repeated item' ) && 2 === substr_count( $html, 'href="/keep/?one=1&amp;two=2"' ), 'List output retains semantic items, repeated copy and complete links' );
	$expect( array( 'classes' => array(), 'styles' => array() ) === mrn_base_stack_get_body_list_contract( array_replace( $body, array( 'list_columns' => '' ) ) ), 'Unset list layout ignores all dormant controls' );
	foreach ( array( '-1px', '1px;color:red', 'var(--unknown)', array( '12px' ) ) as $bad ) {
		$contract = mrn_base_stack_get_body_list_contract( array_replace( $body, array( 'list_item_size' => $bad, 'list_item_weight' => $bad, 'list_item_color' => $bad, 'list_space_before' => $bad ) ) );
		$style = implode( ';', $contract['styles'] ); $expect( ! str_contains( $style, '--mrn-list-item-size:' ) && ! str_contains( $style, '--mrn-list-item-weight:' ) && ! str_contains( $style, '--mrn-list-item-color:' ) && ! str_contains( $style, '--mrn-list-space-before:' ), 'Unsafe optional list values cannot emit CSS' );
	}
	foreach ( array( 'calc(101% - 40px)', 'calc(45% - 201px)', 'calc(45% - -1px)', 'calc(45% + 40px)', 'calc(45% - 40px);color:red', array( '45%' ) ) as $bad ) { $expect( '' === mrn_base_stack_validate_split_column_bound( $bad ), 'Unqualified proportional expression is rejected' ); }
	$expect( 'calc(45% - 40px)' === mrn_base_stack_validate_split_column_bound( 'calc( 45.0% - 40.0px )' ), 'Proportional expressions normalize to bounded numeric terms' );
} finally { wp_delete_post( $id, true ); }
$expect( null === get_post( $id ), 'Owned native service copy fixture removed' );
WP_CLI::line( wp_json_encode( array( 'result' => 'passed', 'count' => count( $checks ), 'checks' => $checks, 'candidate_only' => true ), JSON_PRETTY_PRINT ) );
